        if state['sigma'] <= safe_sigma_threshold:
            # Safe to increase rate slightly
            current_rate = -0.75
        else:
            # Too much supersaturation, reduce rate to be safe
            current_rate = -0.25
    else:
        # Still cooling, maintain conservative rate
        if state['sigma'] <= safe_sigma_threshold:
            # Safe to increase rate slightly
            current_rate = -0.75
        else:
            # Too much supersaturation, reduce rate to be safe
            current_rate = -0.25

    # Ensure rate is within bounds
    return max(-1.0, min(1.0, current_rate))

